import { randomBytes } from 'node:crypto';

let lastMs = -1;
let counter = 0;

/**
 * UUIDv7 (RFC 9562): 48-bit Unix ms timestamp + random bits. Time-ordered, generated by the
 * application. With the default clock, ids from this process are strictly increasing: within one
 * millisecond the 12-bit `rand_a` field is a counter (RFC 9562 §6.2, method 1), so rows inserted in
 * order also sort in that order. An explicit `now` gives a plain, non-monotonic id.
 */
export function uuidv7(now?: number): string {
  const b = randomBytes(16);
  let ms: number;
  if (now === undefined) {
    const clock = Date.now();
    if (clock > lastMs) {
      lastMs = clock;
      counter = b.readUInt16BE(6) & 0x7ff; // random start in the lower half leaves room to count
    } else if (++counter > 0xfff) {
      lastMs++; // counter exhausted: borrow the next millisecond
      counter = 0;
    }
    ms = lastMs;
    b[6] = 0x70 | (counter >> 8);
    b[7] = counter & 0xff;
  } else {
    ms = now;
    b[6] = (b[6]! & 0x0f) | 0x70;
  }
  b[0] = Math.floor(ms / 2 ** 40) & 0xff;
  b[1] = Math.floor(ms / 2 ** 32) & 0xff;
  b[2] = Math.floor(ms / 2 ** 24) & 0xff;
  b[3] = Math.floor(ms / 2 ** 16) & 0xff;
  b[4] = Math.floor(ms / 2 ** 8) & 0xff;
  b[5] = ms & 0xff;
  b[8] = (b[8]! & 0x3f) | 0x80;
  const h = b.toString('hex');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
export const isUuid = (v: unknown): v is string => typeof v === 'string' && UUID_RE.test(v);
